#!/usr/bin/env python3
import paramiko
import struct
import time
import sys
import os
import ctypes
import fcntl
import socket

# Connect to the VM via SSH
def connect_to_vm():
    # First get the latest port from the challenge server
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.connect(('pwn.chal.csaw.io', 23750))
    response = s.recv(4096).decode()
    s.close()

    # Parse SSH info from response
    port_line = [line for line in response.split('\n') if 'SSH port' in line][0]
    port = int(port_line.split(':')[1].strip())

    print(f"Connecting to SSH on port {port}")

    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    # Try to connect with retry
    for _ in range(3):
        try:
            ssh.connect('pwn.chal.csaw.io', port, username='vagrant', password='vagrant')
            print("SSH connection established")
            return ssh
        except Exception as e:
            print(f"SSH connection error: {e}")
            time.sleep(1)

    raise Exception("Failed to connect to SSH after multiple attempts")

# IOCTL constants
IOCTL_KRYPTO = 0x1337

# Connect to SSH
ssh = connect_to_vm()

# Command to execute
cmd = """
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/ioctl.h>

#define KRYPTO_IOCTL 0x1337

int main() {
    int fd = open("/dev/krypto", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open /dev/krypto");
        return 1;
    }

    // Allocate buffer to receive data
    char *buf = malloc(128);
    if (!buf) {
        perror("malloc failed");
        close(fd);
        return 1;
    }

    // Prepare arguments for ioctl
    void *args[2];
    args[0] = buf;           // Output buffer
    args[1] = (void *)128;   // Buffer size

    // Call ioctl
    int ret = ioctl(fd, KRYPTO_IOCTL, args);
    printf("ioctl returned: %d\\n", ret);

    // Print buffer as hex
    printf("Random data: ");
    for (int i = 0; i < 32; i++) {
        printf("%02x ", (unsigned char)buf[i]);
    }
    printf("\\n");

    // Clean up
    free(buf);
    close(fd);
    return 0;
}
"""

# Create and compile the C program
stdin, stdout, stderr = ssh.exec_command("cat > /tmp/test.c << 'EOL'\n" + cmd + "\nEOL")
print("Created test.c")

stdin, stdout, stderr = ssh.exec_command("cd /tmp && gcc -o test test.c")
print("Compiler output:", stderr.read().decode())

# Run the program
stdin, stdout, stderr = ssh.exec_command("cd /tmp && ./test")
output = stdout.read().decode()
error = stderr.read().decode()
print("Output:", output)
print("Errors:", error)

# Now let's check and understand the kernel vulnerability
# Analyze krypto_ioctl again
stdin, stdout, stderr = ssh.exec_command("cat /proc/modules | grep krypto")
modules_output = stdout.read().decode()
print("Kernel module information:", modules_output)

# Let's also look at kernel messages to see any debug info
stdin, stdout, stderr = ssh.exec_command("dmesg | grep -i krypto")
dmesg_output = stdout.read().decode()
print("Kernel messages:", dmesg_output)

# Try to read the flag file directly (although it needs root)
stdin, stdout, stderr = ssh.exec_command("sudo cat /home/vagrant/flag 2>/dev/null || echo 'Permission denied'")
flag_attempt = stdout.read().decode()
print("Flag attempt:", flag_attempt)

# Clean up and close SSH
ssh.close()

#!/usr/bin/env python3
from pwn import *
import paramiko
import re
import time

# Connect to the challenge server to get the SSH port
conn = remote('pwn.chal.csaw.io', 23750)
response = conn.recvuntil(b'SSH Port').decode()
conn.recvuntil(b':')
port_str = conn.recvline().strip().decode()
port = int(port_str)
conn.close()

print(f"Got SSH port: {port}")

# Connect to the VM via SSH
ssh = paramiko.SSHClient()
ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

try:
    ssh.connect('pwn.chal.csaw.io', port, username='vagrant', password='vagrant')
    print("SSH connection established")
except Exception as e:
    print(f"SSH connection error: {e}")
    exit(1)

# Command to execute
cmd = """
#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <string.h>
#include <sys/ioctl.h>

#define KRYPTO_IOCTL 0x1337

int main() {
    int fd = open("/dev/krypto", O_RDONLY);
    if (fd < 0) {
        perror("Failed to open /dev/krypto");
        return 1;
    }

    // Allocate buffer to receive data
    char *buf = malloc(128);
    if (!buf) {
        perror("malloc failed");
        close(fd);
        return 1;
    }

    // Prepare arguments for ioctl
    void *args[2];
    args[0] = buf;           // Output buffer
    args[1] = (void *)128;   // Buffer size

    // Call ioctl
    int ret = ioctl(fd, KRYPTO_IOCTL, args);
    printf("ioctl returned: %d\\n", ret);

    // Print buffer as hex
    printf("Random data: ");
    for (int i = 0; i < 32; i++) {
        printf("%02x ", (unsigned char)buf[i]);
    }
    printf("\\n");

    // Clean up
    free(buf);
    close(fd);
    return 0;
}
"""

# Create and compile the C program
stdin, stdout, stderr = ssh.exec_command("cat > /tmp/test.c << 'EOL'\n" + cmd + "\nEOL")
stdin.channel.shutdown_write()
print("Created test.c")

stdin, stdout, stderr = ssh.exec_command("cd /tmp && gcc -o test test.c")
stdin.channel.shutdown_write()
error = stderr.read().decode()
if error:
    print("Compiler output:", error)

# Run the program
stdin, stdout, stderr = ssh.exec_command("cd /tmp && ./test")
stdin.channel.shutdown_write()
output = stdout.read().decode()
error = stderr.read().decode()
print("Output:", output)
if error:
    print("Errors:", error)

# Check kernel module information
stdin, stdout, stderr = ssh.exec_command("cat /proc/modules | grep krypto")
stdin.channel.shutdown_write()
modules_output = stdout.read().decode()
print("Kernel module information:", modules_output)

# Let's also look at kernel messages
stdin, stdout, stderr = ssh.exec_command("dmesg | grep -i krypto")
stdin.channel.shutdown_write()
dmesg_output = stdout.read().decode()
print("Kernel messages:", dmesg_output)

# Let's examine the memory layout and look for vulnerabilities
stdin, stdout, stderr = ssh.exec_command("cat /proc/kallsyms | grep -i krypto")
stdin.channel.shutdown_write()
kallsyms_output = stdout.read().decode()
print("Kernel symbols:", kallsyms_output)

# Clean up and close SSH
ssh.close()

#!/usr/bin/env python3
from pwn import *
import struct
import fcntl
import array
import ctypes

# IOCTL constants
KRYPTO_IOCTL_CMD = 0x1337

# Connect to the challenge server to get fresh SSH info
try:
    # Connect to the challenge server
    p = remote('pwn.chal.csaw.io', 23750)
    response = p.recvline().decode('utf-8')
    print(f"Server response: {response}")

    # Extract port from response
    import re
    port_match = re.search(r'port (\d+)', response)
    if port_match:
        ssh_port = int(port_match.group(1))
        print(f"Extracted SSH port: {ssh_port}")
    else:
        print("Failed to extract SSH port, using default 30027")
        ssh_port = 30027

    p.close()

    # Connect via SSH
    print(f"[*] Connecting to pwn.chal.csaw.io:{ssh_port} with vagrant:vagrant")
    ssh = ssh(host='pwn.chal.csaw.io', port=ssh_port, user='vagrant', password='vagrant')

    # Basic exploration
    print("\n[*] System Information:")
    print(ssh.system('uname -a'))

    print("\n[*] Files in home directory:")
    print(ssh.system('ls -la ~'))

    print("\n[*] Checking /dev/krypto device:")
    print(ssh.system('ls -la /dev/krypto'))

    # Creating C program to interact with the device
    c_prog = '''
    #include <stdio.h>
    #include <stdlib.h>
    #include <fcntl.h>
    #include <unistd.h>
    #include <string.h>
    #include <sys/ioctl.h>

    #define KRYPTO_IOCTL_CMD 0x1337

    int main() {
        int fd;
        char buffer[1024];
        int ret;

        // Open the device
        fd = open("/dev/krypto", O_RDONLY);
        if (fd < 0) {
            perror("Failed to open /dev/krypto");
            return 1;
        }
        printf("Device opened successfully\\n");

        // Clear the buffer
        memset(buffer, 0, sizeof(buffer));

        // Make IOCTL call
        ret = ioctl(fd, KRYPTO_IOCTL_CMD, buffer);
        printf("IOCTL returned: %d\\n", ret);

        // Display buffer contents
        printf("Buffer contents (hex):\\n");
        for (int i = 0; i < 64; i++) {
            printf("%02x ", (unsigned char)buffer[i]);
            if ((i + 1) % 16 == 0) printf("\\n");
        }

        // Close the device
        close(fd);
        return 0;
    }
    '''

    # Upload and compile the C program
    print("\n[*] Creating and compiling C program...")
    ssh.set_working_directory()
    ssh.write('krypto_interact.c', c_prog)
    print(ssh.system('gcc -o krypto_interact krypto_interact.c'))

    # Run the program
    print("\n[*] Running the program:")
    print(ssh.system('./krypto_interact'))

    # Create a second program to test reading from the device
    c_prog2 = '''
    #include <stdio.h>
    #include <stdlib.h>
    #include <fcntl.h>
    #include <unistd.h>
    #include <string.h>

    int main() {
        int fd;
        char buffer[1024];
        int ret;

        // Open the device
        fd = open("/dev/krypto", O_RDONLY);
        if (fd < 0) {
            perror("Failed to open /dev/krypto");
            return 1;
        }
        printf("Device opened successfully\\n");

        // Clear the buffer
        memset(buffer, 0, sizeof(buffer));

        // Read from the device
        ret = read(fd, buffer, sizeof(buffer));
        printf("Read returned: %d bytes\\n", ret);

        // Display buffer contents
        printf("Buffer contents (hex):\\n");
        for (int i = 0; i < ret && i < 64; i++) {
            printf("%02x ", (unsigned char)buffer[i]);
            if ((i + 1) % 16 == 0) printf("\\n");
        }

        // Close the device
        close(fd);
        return 0;
    }
    '''

    # Upload and compile the second program
    print("\n[*] Creating and compiling second program...")
    ssh.write('krypto_read.c', c_prog2)
    print(ssh.system('gcc -o krypto_read krypto_read.c'))

    # Run the second program
    print("\n[*] Running the second program:")
    print(ssh.system('./krypto_read'))

    # Try to examine the krypto module further
    print("\n[*] Examining module symbols:")
    print(ssh.system('cat /proc/kallsyms | grep krypto'))

    # Create a more advanced program to test different ioctl commands
    c_prog3 = '''
    #include <stdio.h>
    #include <stdlib.h>
    #include <fcntl.h>
    #include <unistd.h>
    #include <string.h>
    #include <sys/ioctl.h>

    int main() {
        int fd;
        unsigned long cmd;
        char buffer[1024];
        int ret;

        // Open the device
        fd = open("/dev/krypto", O_RDONLY);
        if (fd < 0) {
            perror("Failed to open /dev/krypto");
            return 1;
        }
        printf("Device opened successfully\\n");

        // Test different IOCTL commands
        unsigned long commands[] = {0x1337, 0x1338, 0x1339, 0x133A};

        for (int i = 0; i < sizeof(commands)/sizeof(commands[0]); i++) {
            cmd = commands[i];
            memset(buffer, 0, sizeof(buffer));

            printf("\\nTrying IOCTL command: 0x%lx\\n", cmd);
            ret = ioctl(fd, cmd, buffer);
            printf("IOCTL returned: %d\\n", ret);

            if (ret >= 0) {
                printf("Buffer contents (hex):\\n");
                for (int j = 0; j < 64; j++) {
                    printf("%02x ", (unsigned char)buffer[j]);
                    if ((j + 1) % 16 == 0) printf("\\n");
                }
            }
        }

        // Close the device
        close(fd);
        return 0;
    }
    '''

    # Upload and compile the third program
    print("\n[*] Creating and compiling third program...")
    ssh.write('krypto_test.c', c_prog3)
    print(ssh.system('gcc -o krypto_test krypto_test.c'))

    # Run the third program
    print("\n[*] Running the third program:")
    print(ssh.system('./krypto_test'))

    # Close SSH connection
    ssh.close()

except Exception as e:
    print(f"[!] Error: {e}")

